]'::jsonb) as x(room integer,title text,region text,zone text,mob_level text,base_count text,key_chance text,fog_chance text,encounters jsonb,enemies jsonb,ranks jsonb,mutation_line text,weapon_chance text,armor_chance text,gear_chances jsonb,weapon_table jsonb,armor_table jsonb) on conflict(room_number) do update set room_type=excluded.room_type,region=excluded.region,zone=excluded.zone,mob_level=excluded.mob_level,base_count=excluded.base_count,room_key_chance=excluded.room_key_chance,fog_chance=excluded.fog_chance,encounters=excluded.encounters,enemies=excluded.enemies,ranks=excluded.ranks,mutation_summary=excluded.mutation_summary,weapon_chance=excluded.weapon_chance,armor_chance=excluded.armor_chance,gear_chances=excluded.gear_chances,weapon_table=excluded.weapon_table,armor_table=excluded.armor_table;
